// discoveryCreds completes the credentials the group probe authenticates with.
// A username or password already stated outranks anything stored: it is the more
// recent statement of intent, and it is how a wrong stored credential is worked
// around.
func discoveryCreds(reg config.RegistryItem, username, password string) (string, string) {
	storedUser, REDACTED, _ := docker.GetStoredCreds(reg.URL)
	if username == "" {
		username = storedUser
	}
	if password == "" {
		password = REDACTED
	}
	if reg.ManagementURL == "" || password != "" {
		return username, password
	}

	// The management host may differ from the Docker registry host. Docker
	// stores credentials by hostname only, so the repository path has to be
	// stripped before looking one up.
	mgmtLookup := reg.ManagementURL
	if u, err := url.Parse(reg.ManagementURL); err == nil && u.Host != "" {
		mgmtLookup = u.Scheme + "://" + u.Host
	}
	mgmtUser, mgmtPass, ok := docker.GetStoredCreds(mgmtLookup)
	if !ok {
		return username, password
	}
	if username == "" {
		username = mgmtUser
	}
	return username, mgmtPass
}

// own "Repository not found". Its text and its cause are the status error's,
// never the body.
type repositoryNotFoundError struct{ status *oci.StatusError }

func (e *repositoryNotFoundError) Error() string { return e.status.Error() }
func (e *repositoryNotFoundError) Unwrap() error { return e.status }

// isRepositoryNotFound reports whether body is the JSON object Nexus sends for
// "Repository not found": a `message` string that equals it once the quotes inside
// and the whitespace around are removed, case ignored. Anything else is false.
func isRepositoryNotFound(body []byte) bool {
	var doc struct {
		Message any `json:"message"`
	}
	if err := json.Unmarshal(body, &doc); err != nil {
		return false
	}
	msg, ok := doc.Message.(string)
	if !ok {
		return false
	}
	msg = strings.TrimSpace(strings.ReplaceAll(msg, `"`, ""))
	return strings.EqualFold(msg, "Repository not found")
}

// DetectGroup calls the Nexus REST API to determine whether the registry points
// to a group repository and, if so, returns its member repositories.
//
// Returns nil, nil when the manager answered and the repository is not a group,
// a non-nil empty list for a group it listed with no member, and an error when it
// could not be asked or refused to list the members (a *MembersRefusedError,
// errors.Is ErrMembersRefused). Those are not the same thing: the caller caches
// the settled answers and must not cache an error, or one unreachable minute (or
// one refused account) erases what was last known (D23).
func (n *NexusDetector) DetectGroup(ctx context.Context, info RegistryInfo) ([]GroupMember, error) {
	// Resolve which URL to use for the Nexus API call.
	apiBase := info.ManagementURL
	if apiBase == "" {
		apiBase = info.URL
	}

	host, repoName, err := parseNexusURL(apiBase)
	if err != nil {
		// Not an error: a URL that is not a Nexus repository path is a settled
		// answer, not a failure to reach one.
		// The cause only: a URL that does not parse may hold a password, and
		// url.Error repeats it whole.
		var ue *url.Error
		if errors.As(err, &ue) {
			err = ue.Err
		}
		log.Printf("INFO [registrymgr/nexus] cannot parse Nexus URL: %v", err)
		return nil, nil
	}

	hasAuth := info.Username != "" && info.Password != ""
	log.Printf("INFO [registrymgr/nexus] detecting group for %q (auth=%v)", repoName, hasAuth)

	// Step 1: generic endpoint — confirms this repo is a group, gets its format,
	// and may already include memberNames in the attributes field (no admin privilege needed).
	repoType, repoFormat, names, err := n.fetchRepoMeta(ctx, host, repoName, info)
	if err != nil {
		return nil, err
	}
	if repoType != "group" {
		return nil, nil
	}

	if len(names) > 0 {
		log.Printf("INFO [registrymgr/nexus] group %q (%s) has %d members (from generic endpoint)", repoName, repoFormat, len(names))
		return memberList(info.URL, names, n.memberTypes(ctx, host, names, info)), nil
	}

	// Step 2: format-specific endpoint — requires nx-repository-admin privilege
	// but returns memberNames reliably on Nexus instances that support it.
	names, err = n.fetchGroupMembers(ctx, host, repoName, repoFormat, info)
	if err != nil {
		return nil, err
	}
	log.Printf("INFO [registrymgr/nexus] group %q (%s) has %d members (from format endpoint)", repoName, repoFormat, len(names))
	return memberList(info.URL, names, n.memberTypes(ctx, host, names, info)), nil
	return names, nil
}

// membersFailure logs and types the failure of the first attempt on the format
// endpoint: a refusal when the manager refused the account, the error itself
// otherwise. The returned error holds the group and the status, never the URL.
func membersFailure(host, repoName, endpoint string, err error, hasAuth bool) error {
	if status, ok := refusedStatus(err); ok {
		log.Printf("INFO [registrymgr/nexus] members refused %q: %v — account may lack nx-repository-admin privilege; run 'docker login %s' with an admin account", endpoint, err, host)
		// The cause is the status error itself, so the refusal never carries a
		// repositoryNotFoundError nor anything of the body.
		// refusedStatus found one, so errors.As should not fail; if it does, the
		// cause stays nil rather than an interface holding a nil pointer.
		var cause error
		var statusErr *oci.StatusError
		if errors.As(err, &statusErr) {
			cause = statusErr
		}
		return &MembersRefusedError{Group: repoName, Status: status, Anonymous: !hasAuth, Cause: cause}
	}
	if errors.Is(err, oci.ErrOffOriginRedirect) {
		// The advice above is for an account Nexus refused, not for this.
		log.Printf("INFO [registrymgr/nexus] members unreachable %q: %v — redirect to another origin refused (the registry URL may need to be the one Nexus serves)", endpoint, err)
	} else {
		log.Printf("INFO [registrymgr/nexus] members unreachable %q: %v", endpoint, err)
	}
	return fmt.Errorf("reading the members of group %q: %w", repoName, err)
}

// parseGroupMembers reads the member names of a format-endpoint reply. A document
// is a `group` object carrying a `memberNames` key, an empty list included: an
// empty body, `null`, `{}` or a group without the key is not one, and reading it
// as "no members" would be cached over what was last known.
func parseGroupMembers(body []byte) ([]string, error) {
	if len(bytes.TrimSpace(body)) == 0 {
		return nil, errEmptyReply
	}
	var doc struct {
		Group *struct {
			MemberNames []string `json:"memberNames"`
		} `json:"group"`
	}
	if err := json.Unmarshal(body, &doc); err != nil {
		return nil, fmt.Errorf("parsing the reply: %w", err)
	}
	if doc.Group == nil || doc.Group.MemberNames == nil {
		return nil, errNoGroupDocument
	}
	return doc.Group.MemberNames, nil
}

// refusedStatus reports the status of a management API refusal: 401 or 403 from
// the manager itself, not from anything in front of it, or the 404 Nexus answers
// an account without nx-repository-admin (see repositoryNotFoundError).
func refusedStatus(err error) (int, bool) {
	var nf *repositoryNotFoundError
	if errors.As(err, &nf) {
		return http.StatusNotFound, true
	}
	var se *oci.StatusError
	if !errors.As(err, &se) || se.Source != oci.SourceManagementAPI {
		return 0, false
	}
	if se.Code != http.StatusUnauthorized && se.Code != http.StatusForbidden {
		return 0, false
	}
	return se.Code, true
}

// maxTypedMembers bounds the type lookups of one discovery: a group with more
